USE sql_notes;
WITH avg_m AS (SELECT e.student_id, AVG(m.marks_obtained) AS a FROM enrollments e JOIN marks m ON m.enrollment_id = e.enrollment_id GROUP BY e.student_id) SELECT s.name, ROUND(avg_m.a, 2) AS avg_marks FROM students s JOIN avg_m ON avg_m.student_id = s.student_id ORDER BY s.student_id;
WITH avg_m AS (SELECT e.student_id, AVG(m.marks_obtained) AS a FROM enrollments e JOIN marks m ON m.enrollment_id = e.enrollment_id GROUP BY e.student_id) SELECT s.name FROM students s JOIN avg_m ON avg_m.student_id = s.student_id WHERE avg_m.a > 79.125;
WITH RECURSIVE nums AS (SELECT 1 AS n UNION ALL SELECT n + 1 FROM nums WHERE n < 5) SELECT * FROM nums;
SELECT m.marks_obtained, RANK() OVER (ORDER BY m.marks_obtained DESC) AS r FROM marks m ORDER BY r;
SELECT c.course_name, s.name, m.marks_obtained, RANK() OVER (PARTITION BY e.course_id ORDER BY m.marks_obtained DESC) AS r FROM students s JOIN enrollments e ON s.student_id = e.student_id JOIN courses c ON e.course_id = c.course_id JOIN marks m ON m.enrollment_id = e.enrollment_id ORDER BY c.course_name, r;
WITH r AS (SELECT marks_obtained, ROW_NUMBER() OVER (ORDER BY marks_obtained DESC) AS rn FROM marks) SELECT * FROM r WHERE rn = 2;
SELECT m.marks_obtained, LAG(m.marks_obtained) OVER (ORDER BY m.marks_obtained DESC) AS prev_m FROM marks m ORDER BY m.marks_obtained DESC;
SELECT m.marks_obtained, LEAD(m.marks_obtained) OVER (ORDER BY m.marks_obtained DESC) AS next_m FROM marks m ORDER BY m.marks_obtained DESC;
SELECT e.enrollment_id, m.marks_obtained, SUM(m.marks_obtained) OVER (ORDER BY e.enrollment_id ROWS UNBOUNDED PRECEDING) AS run_tot FROM enrollments e JOIN marks m ON m.enrollment_id = e.enrollment_id ORDER BY e.enrollment_id;
SELECT e.enrollment_id, m.marks_obtained, ROUND(AVG(m.marks_obtained) OVER (ORDER BY e.enrollment_id ROWS BETWEEN 1 PRECEDING AND 1 FOLLOWING), 2) AS mov3 FROM enrollments e JOIN marks m ON m.enrollment_id = e.enrollment_id ORDER BY e.enrollment_id;
CREATE OR REPLACE VIEW v_adv_avg AS SELECT s.name, ROUND(AVG(m.marks_obtained), 2) AS a FROM students s JOIN enrollments e ON s.student_id = e.student_id JOIN marks m ON m.enrollment_id = e.enrollment_id GROUP BY s.name;
SELECT * FROM v_adv_avg ORDER BY a DESC;
EXPLAIN SELECT * FROM students WHERE student_id = 1;
EXPLAIN SELECT name FROM students WHERE dept_id = 1;
SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = 'sql_notes' ORDER BY TABLE_NAME;
SELECT name FROM students WHERE enrollment_year = 2023;
WITH r AS (SELECT e.course_id, s.name, m.marks_obtained, ROW_NUMBER() OVER (PARTITION BY e.course_id ORDER BY m.marks_obtained DESC) AS rn FROM enrollments e JOIN students s ON s.student_id = e.student_id JOIN marks m ON m.enrollment_id = e.enrollment_id) SELECT * FROM r WHERE rn = 1;
WITH r AS (SELECT e.course_id, m.marks_obtained, ROW_NUMBER() OVER (PARTITION BY e.course_id ORDER BY m.marks_obtained DESC) AS rn FROM enrollments e JOIN marks m ON m.enrollment_id = e.enrollment_id) SELECT * FROM r WHERE rn = 2;
SELECT s.name, c.course_name, m.marks_obtained, LAG(m.marks_obtained) OVER (PARTITION BY s.student_id ORDER BY m.marks_obtained DESC) AS prev_m FROM students s JOIN enrollments e ON s.student_id = e.student_id JOIN courses c ON e.course_id = c.course_id JOIN marks m ON m.enrollment_id = e.enrollment_id ORDER BY s.name, m.marks_obtained DESC;
WITH sm AS (SELECT s.student_id, s.name, s.dept_id, AVG(m.marks_obtained) AS a FROM students s JOIN enrollments e ON s.student_id = e.student_id JOIN marks m ON m.enrollment_id = e.enrollment_id GROUP BY s.student_id, s.name, s.dept_id) SELECT name, ROUND(a, 2) AS avg_marks, ROUND(AVG(a) OVER (PARTITION BY dept_id), 2) AS dept_avg FROM sm;
SELECT s.name, m.marks_obtained, NTILE(4) OVER (ORDER BY m.marks_obtained DESC) AS q FROM students s JOIN enrollments e ON s.student_id = e.student_id JOIN marks m ON m.enrollment_id = e.enrollment_id ORDER BY m.marks_obtained DESC;
SELECT student_id FROM enrollments WHERE course_id = 1 UNION SELECT student_id FROM enrollments WHERE course_id = 3;
SELECT student_id FROM enrollments WHERE course_id = 1 UNION ALL SELECT student_id FROM enrollments WHERE course_id = 3;
CREATE INDEX idx_q22 ON enrollments(course_id, semester);
EXPLAIN SELECT * FROM enrollments WHERE course_id = 1 AND semester = 3;
DROP INDEX idx_q22 ON enrollments;
DROP TEMPORARY TABLE IF EXISTS tmp_top;
CREATE TEMPORARY TABLE tmp_top AS SELECT * FROM marks WHERE marks_obtained >= 85;
SELECT COUNT(*) FROM tmp_top;
DROP TEMPORARY TABLE tmp_top;
WITH RECURSIVE sems AS (SELECT 1 AS s UNION ALL SELECT s + 1 FROM sems WHERE s < 8) SELECT * FROM sems;
START TRANSACTION;
WITH low AS (SELECT enrollment_id FROM marks WHERE marks_obtained < 60) UPDATE marks SET grade = 'D' WHERE enrollment_id IN (SELECT enrollment_id FROM low);
SELECT * FROM marks WHERE enrollment_id = 5;
ROLLBACK;
SHOW VARIABLES LIKE 'event_scheduler';
EXPLAIN ANALYZE SELECT * FROM marks WHERE marks_obtained > 85;
SELECT COUNT(*) AS orphans FROM enrollments e LEFT JOIN students s ON e.student_id = s.student_id WHERE s.student_id IS NULL;
SELECT TABLE_NAME, CONSTRAINT_NAME FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA = 'sql_notes' AND CONSTRAINT_TYPE = 'FOREIGN KEY';
DROP TEMPORARY TABLE IF EXISTS tmp_s;
CREATE TEMPORARY TABLE tmp_s AS SELECT * FROM students;
DELETE FROM tmp_s WHERE student_id = 5;
SELECT COUNT(*) FROM tmp_s;
DROP TEMPORARY TABLE tmp_s;
SELECT COUNT(*) FROM students;
DROP VIEW IF EXISTS v_adv_avg;
